setup_failure.command:
node --input-type=module <<'NODE'
import { readFile } from 'node:fs/promises';
import { build } from 'esbuild';
import { createRequire } from 'node:module';
process.on('uncaughtException',e=>{console.error(e.name,e.code??'',e.message.split('data:')[0]);process.exitCode=1;});
const source = (await readFile('src/routes/realtime.sdkContract.test.ts','utf8')).split("describe(")[0].replace(/^import .*from 'vitest';\r?\n/m,'') + '\nimport { write, invalidateCache } from '../config/versionedStore'; import { CONTENT_KIND, SLOTS_KIND, LEARN_KIND } from '../content/kinds'; export { boundary, newAnonymousSession, write, invalidateCache, CONTENT_KIND, SLOTS_KIND, LEARN_KIND };\n';
const built = await build({stdin:{contents:source,resolveDir:process.cwd()+'/src/routes',sourcefile:'w0504-existing-boundary.ts',loader:'ts'},bundle:true,write:false,platform:'node',format:'cjs',packages:'external',tsconfig:'tsconfig.json',logLevel:'silent'});
const module={exports:{}};new Function('require','module','exports',built.outputFiles[0].text)(createRequire(import.meta.url),module,module.exports);
const {boundary,newAnonymousSession,write,invalidateCache,CONTENT_KIND,SLOTS_KIND,LEARN_KIND}=module.exports;
globalThis.fetch=async()=>{throw new Error('Outbound prohibited in W05.04 synthetic baseline');};

for (const host of ['session','do']) {
 const f=boundary(host), g=await newAnonymousSession(f.env,'meridian');
 const effects=[]; const ns=label=>({idFromName:n=>n,get:()=>({fetch:async(input,init)=>{effects.push(label+':'+(init?.method??'GET')+':'+new URL(input).pathname);return Response.json({ok:true,entries:[]});}})});
 Object.assign(f.env,{DECISION_RING:ns('ring'),LEARN_STATS:ns('learn'),ANALYTICS:{writeDataPoint:()=>effects.push('analytics')},EVENT_QUEUE:{sendBatch:async rows=>effects.push('queue:'+rows.length)}});
 for (const [kind,value] of [[CONTENT_KIND,{pieces:[{id:'A',customerContentId:'cms-A',type:'editorial',title:'A',tags:{line:['Rogue']},slotTypes:['hero']},{id:'B',customerContentId:'cms-B',type:'editorial',title:'B',tags:{line:['Tabby']},slotTypes:['hero']}]}],[SLOTS_KIND,{pages:{home:[{slot:'hero',take:1,weights:{line:0.5}}]}}],[LEARN_KIND,{holdout:{share:0,salt:'',arms:['default']}}]]) {
  const result=await write(f.env,kind,'meridian',value,{actor:'synthetic'}); if(!result.ok)throw Error('fixture rejected');
 }
 invalidateCache();
 const path='/v1/meridian/decisions/snapshot?page=home&channel=direct';
 const summary=b=>({arm:b.arm,consent:b.sources?.consent,cell:b.cell,winner:b.records?.[0]?.content_id??b.records?.[0]?.contentId,score:b.records?.[0]?.score,records:b.records?.length,write:b.write});
 const decide=async(cookie)=>{effects.length=0;f.sessions.calls.length=0;f.effects.length=0;const r=await f.call(path,g.capability,undefined,'meridian',cookie,{country:'US',regionCode:'NY'});const b=await r.json();await f.drain();return {status:r.status,...summary(b),sessionPuts:f.sessions.calls.filter(x=>x.startsWith('put:')).length,effects:[...effects],objectWrites:f.effects.filter(x=>x.startsWith('store:'))};};
 const cold=await decide('opt_tracking_consent=false; opt_personalization_enabled=false');
 const p=await f.call('/realtime/session/'+g.sessionId+'/preferences',g.capability,{trackingConsent:true,personalizationEnabled:true});if(p.status!==200)throw Error('preference '+p.status);
 for(let i=0;i<3;i++){const r=await f.call('/realtime/action',g.capability,{userId:g.subject,sessionId:g.sessionId,type:'add_to_cart',source:'sdk',data:{productId:'COA-CH857'}});if(r.status!==200)throw Error('warm action '+r.status);}
 await f.drain();
 const positive=await decide();
 const immediateFalseCookie=await decide('opt_tracking_consent=false; opt_personalization_enabled=false');
 const subsequentNoHint=await decide();
 const q=await f.call('/realtime/session/'+g.sessionId+'/preferences',g.capability,{trackingConsent:false,personalizationEnabled:false});if(q.status!==200)throw Error('refusal '+q.status);
 const storedRefusal=await decide();
 console.log(JSON.stringify({host,cold,positive,immediateFalseCookie,subsequentNoHint,storedRefusal}));
}

NODE

